/* B4 integration: browsing/favorites are optional; required application earns completion. */
'use strict';
function teachingEntry(course=currentCourse(),snapshot){
 if(!course)return null;const signature=TaskWorkshop.signature(course);
 snapshot??=state?.banks?.find(b=>b.syllabus===course)?.teachingSnapshot;
 // A saved bank owns its exact binding, even if the same course gets a new sidecar.
 if(snapshot){if([4,5].includes(snapshot.revision)&&snapshot.courseId===course.id&&snapshot.signature===signature&&/^[a-f0-9]{64}$/.test(snapshot.binding)&&Array.isArray(snapshot.chapters))return {...snapshot,course};return null;}
 return Object.values(TeachingCatalog).find(e=>e.course.id===course.id&&e.signature===signature)||null;
}
const teachingEngines=new Map();
function teachingContext(){const entry=teachingEntry();if(!entry)return null;const b=L.bank(state);if(!b.teachingSnapshot){const {course,...snapshot}=entry;b.teachingSnapshot=JSON.parse(JSON.stringify({...snapshot,courseId:course.id}));}state.teachingFlows??={};const key=state.selected+':'+entry.binding,flow=teachingEngines.get(entry.binding)||TeachingFlow.create(entry);teachingEngines.set(entry.binding,flow);const p=state.teachingFlows[key]??=flow.fresh();p.found??=[...new Set(p.favorites)];return {entry,flow,p,s:studyState()};}
function openTeachingCourse(which='legacy'){
 const entry=TeachingCatalog[which];let b=state.banks.find(b=>b.syllabus?.id===entry.course.id&&b.teachingSnapshot?.binding===entry.binding);
 if(!b){b=L.addBank(state,{title:entry.course.title,kind:'已审教学 · 探索版4',cards:CourseSchema.cards(entry.course)},Date.now());b.syllabus=JSON.parse(JSON.stringify(entry.course));b.focus='1.1';state.chapterStudies??={};state.chapterStudies[b.id]=CS.fresh();}
 state.selected=b.id;state.zone=currentCourse().chapters[studyState().chapter].zone;state.guide=true;L.start(state,Date.now(),true);A.session(state);teachingContext();close();renderWorld();resetCamera();save();
}
const teachingInit=initExamWorld;
initExamWorld=function(){const existing=!!examBank();teachingInit();if(!existing){openTeachingCourse();showGameGuide(true);}};
const teachingDock=renderExamDock;
renderExamDock=function(){teachingDock();if(!currentCourse()||teachingEntry())return;const button=document.createElement('button');button.id='openTeachingEdition';button.textContent=learningCopy('开启新版探索课程（旧进度保留）','Open exploration edition (keep existing progress)');button.onclick=()=>openTeachingCourse();$('chapterDock').appendChild(button);};
const teachingTheme=studyTheme;
studyTheme=function(sec=studySection(),chapter=studyState().chapter){const theme=teachingTheme(sec,chapter);return teachingEntry()?{...theme,container:wt(sec.activity.title),kind:sec.activity.kind}:theme;};
function teachingReturnTo(reopen){const bank=state.selected,dialogTop=$('dialog').scrollTop||0,bodyTop=$('dialogBody').scrollTop||0;return()=>{if(state.selected!==bank){close();return;}reopen();const restore=()=>{$('dialog').scrollTop=dialogTop;$('dialogBody').scrollTop=bodyTop;};if(typeof requestAnimationFrame==='function')requestAnimationFrame(restore);else restore();};}
const teachingLesson=openStudyLesson;
openStudyLesson=function(id,reference=false,returnTo=null,foundInScene=false){const ctx=teachingContext();if(!ctx)return teachingLesson(id,reference);const {entry,flow,p,s}=ctx,access=lessonAccess(id),lesson=access.section?.lessons.find(l=>l.id===id);if(!lesson)return;
 if(foundInScene&&access.section?.id===studySection().id&&!p.found.includes(id)){p.found.push(id);render();if(studySection().lessons.every(l=>p.found.includes(l.id)))toast(learningCopy('本节知识物件已全部找到！读完后放入整理柜，继续应用工坊。','All knowledge objects in this section found! Read and file them, then continue to the application workshop.'));}if(!p.viewed.includes(id))p.viewed.push(id);save();const step=flow.foundation(access.section.id,id),ready=step&&flow.gate(p,s,step.id),confirmed=step&&p.foundations.includes(step.id);
 modal(`${returnTo?`<button id="lessonBack" class="lesson-back">${learningCopy('← 返回上一页','← Back')}</button>`:''}<span class="eyebrow">${learningCopy('自由知识浏览 · 收藏不算掌握','Free knowledge browsing · favorites are not mastery')}</span><h2 id="dialogTitle">${esc(knowledgeText(lesson,'title'))}</h2><h3>${learningCopy('定义','Definition')}</h3>${studyText(knowledgeText(lesson,'body'))}<h3>${learningCopy('应用示例','Example')}</h3><p>${esc(knowledgeText(lesson,'example'))}</p><p class="knowledge-boundary">${esc(knowledgeText(lesson,'boundary'))}</p><details class="source-detail"><summary>${learningCopy('学习目标与依据','Learning objective and evidence')}</summary><p>${esc(knowledgeText(lesson,'quote'))}</p><p>${esc(lesson.source)}</p>${knowledgeReferenceLinks(lesson)}</details><p role="status">${confirmed?learningCopy('已确认基础；理解由后续应用检验。','Foundation confirmed; subsequent applications check understanding.'):ready?learningCopy('可确认本基础；收藏并非必需。','You may confirm this foundation; collecting is optional.'):learningCopy('可以自由阅读；先完成上游基础或应用，再确认。','Read freely; complete upstream foundations or applications before confirming.')}</p><div class="actions"><button id="leaveLesson">${learningCopy('返回场景','Back to scene')}</button><button id="favoriteKnowledge" ${p.found.includes(id)||p.favorites.includes(id)?'':'disabled'}>${p.favorites.includes(id)?learningCopy('取消收藏','Remove favorite'):p.found.includes(id)?learningCopy('收藏知识（可选）','Favorite knowledge (optional)'):learningCopy('先在场景找到这件物品','Find this object in the scene first')}</button><button id="confirmFoundation" class="primary" ${ready&&!confirmed?'':'disabled'}>${learningCopy('确认基础，准备应用','Confirm foundation and prepare to apply')}</button></div>`,true);
 if($('lessonBack'))$('lessonBack').onclick=returnTo;
 $('leaveLesson').onclick=close;$('favoriteKnowledge').onclick=()=>{if(!p.found.includes(id)&&!p.favorites.includes(id))return;p.favorites=p.favorites.includes(id)?p.favorites.filter(x=>x!==id):[...p.favorites,id];if(heldTeachingFavorite===id)heldTeachingFavorite=null;save();render();openStudyLesson(id,reference,returnTo);};
 $('confirmFoundation').onclick=()=>{if(!step||!flow.gate(p,s,step.id)||p.foundations.includes(step.id))return;p.foundations.push(step.id);s.read.push(...[id].filter(x=>!s.read.includes(x)));s.carried=s.carried.filter(x=>x!==id);if(!s.deposited.includes(id))s.deposited.push(id);render();save();(returnTo||openStudyBasket)();};
};
const teachingBasket=openStudyBasket;
let heldTeachingFavorite=null,heldTeachingBank=null;
function teachingFavoriteLessons(ctx=teachingContext()){return ctx?currentCourse().chapters.flatMap(ch=>ch.sections.flatMap(sec=>sec.lessons)).filter(l=>ctx.p.favorites.includes(l.id)):[];}
function teachingFavoriteHTML(includeFiled=false){const ctx=teachingContext();return `<div class="teaching-favorites"><strong>${includeFiled?learningCopy('收藏与归档','Favorites and archive'):learningCopy('随身收藏','Collected keepsakes')}</strong><small>${learningCopy('单击选中，再点整理柜放入；双击查看，也可拖动放入。','Click to select, then click the filing cabinet to place. Double-click to read, or drag to file.')}</small>${teachingFavoriteLessons(ctx).filter(l=>includeFiled||!ctx.s.deposited.includes(l.id)).map(l=>`<div class="teaching-favorite"><button ${includeFiled&&ctx.s.deposited.includes(l.id)?`data-archived-favorite="${l.id}"`:`data-teaching-favorite="${l.id}" draggable="true"`} aria-pressed="${heldTeachingFavorite===l.id}">${explorationArt('knowledge',discoveryProp(l).mode)}<span>${esc(knowledgeText(l,'title'))}</span></button></div>`).join('')||`<p>${learningCopy('收藏的知识物件会出现在这里。','Your favorite knowledge objects appear here.')}</p>`}</div>`;}
function wireTeachingFavorites(){document.querySelectorAll('[data-archived-favorite]').forEach(el=>el.onclick=()=>openStudyLesson(el.dataset.archivedFavorite,true,teachingReturnTo(showKnowledgeChest)));document.querySelectorAll('[data-teaching-favorite]').forEach(el=>{const id=el.dataset.teachingFavorite;el.onclick=()=>{heldTeachingFavorite=id;heldTeachingBank=state.selected;document.querySelectorAll('[data-teaching-favorite]').forEach(item=>item.setAttribute?.('aria-pressed',String(item.dataset.teachingFavorite===id)));toast(learningCopy('已选中收藏物件，点击本节整理柜放入。','Favorite selected. Click this section’s filing cabinet to place it.'));};el.ondblclick=e=>{e?.preventDefault?.();e?.stopPropagation?.();openStudyLesson(id,true,$('dialog').open?teachingReturnTo(showKnowledgeChest):null);};bindDraggable(el,{teachingFavorite:id,bank:state.selected});});document.querySelectorAll('[data-favorite-read]').forEach(el=>el.onclick=()=>openStudyLesson(el.dataset.favoriteRead,true));}
function placeTeachingFavorite(id){const ctx=teachingContext();if(!ctx||!ctx.p.favorites.includes(id))return false;const sec=studySection(),step=ctx.flow.foundation(sec.id,id);if(!step){toast(learningCopy('这件收藏属于其他小节，可回看，暂不能放入本节整理柜。','This favorite belongs to another section. You can read it, but cannot file it here.'));return false;}if(ctx.p.foundations.includes(step.id)){toast(learningCopy('这项基础已经确认，可以继续应用。','This foundation is already confirmed; continue to its applications.'));return false;}if(!ctx.flow.gate(ctx.p,ctx.s,step.id)){toast(learningCopy('先确认前面的基础，再放入这件物品。','Confirm the preceding foundations before filing this item.'));return false;}ctx.p.foundations.push(step.id);if(!ctx.s.read.includes(id))ctx.s.read.push(id);ctx.s.carried=ctx.s.carried.filter(x=>x!==id);if(!ctx.s.deposited.includes(id))ctx.s.deposited.push(id);heldTeachingFavorite=null;close();render();save();toast(learningCopy('物件已放入，基础已确认；完成应用才能通过本节。','Item filed and foundation confirmed. Complete the applications to finish this section.'));return true;}
const teachingFavoriteDrag=applyDrag;
applyDrag=function(data,kind,category){if(data?.teachingFavorite){if(data.bank===state.selected&&kind==='study-basket')placeTeachingFavorite(data.teachingFavorite);return;}return teachingFavoriteDrag(data,kind,category);};
const teachingFavoriteTray=renderTray;
renderTray=function(){teachingFavoriteTray();const ctx=teachingContext();if(heldTeachingBank!==state.selected||!ctx?.p.favorites.includes(heldTeachingFavorite)||ctx?.s.deposited.includes(heldTeachingFavorite))heldTeachingFavorite=null;if(!ctx)return;const shelf=document.createElement('section');shelf.id='teachingFavoriteTray';shelf.innerHTML=teachingFavoriteHTML();$('adventureTray').appendChild(shelf);wireTeachingFavorites();const sec=studySection();if(sec.lessons.every(l=>ctx.p.found.includes(l.id))){const notice=document.createElement('div');notice.id='sectionFoundNotice';notice.className='section-found-notice';notice.setAttribute?.('role','status');const ready=ctx.flow.ready(ctx.p,ctx.s,sec.id);notice.innerHTML=`<span>${ready?learningCopy('本节已找齐并整理完毕，可以开始应用。','All section objects found and filed. Ready to apply.'):learningCopy('本节物件已全部找到！下一步：把知识放入整理柜。','All section objects found! Next: file the knowledge in the cabinet.')}</span><button id="sectionFoundNext">${ready?learningCopy('开始应用','Start applications'):learningCopy('前往整理柜','Open filing cabinet')}</button>`;$('adventureTray').appendChild(notice);$('sectionFoundNext').onclick=ready?openTaskWorkshop:openStudyBasket;}};
const teachingFavoriteLoot=renderLoot;
renderLoot=function(){teachingFavoriteLoot();const ctx=teachingContext();if(!ctx)return;for(const selector of ['[data-study-fruit]','[data-study-filed]'])document.querySelectorAll(selector).forEach(el=>{if(ctx.p.favorites.includes(el.dataset.studyFruit||el.dataset.studyFiled))el.remove();});[...document.querySelectorAll('[data-study-fruit]'),...document.querySelectorAll('[data-study-filed]')].forEach(el=>{el.onclick=e=>{if(Date.now()<suppressClick)return;e?.stopPropagation?.();openStudyLesson(el.dataset.studyFruit||el.dataset.studyFiled,false,null,true);};});const basket=$('worldStudyBasket');if(basket){const base=basket.onclick;basket.onclick=e=>heldTeachingFavorite?placeTeachingFavorite(heldTeachingFavorite):base?.(e);}};
const teachingFavoriteChest=showKnowledgeChest;
showKnowledgeChest=function(){teachingFavoriteChest();if(!teachingContext())return;const shelf=document.createElement('section');shelf.id='teachingFavoriteShelf';shelf.innerHTML=teachingFavoriteHTML(true);const body=$('dialogBody');if(body.insertBefore)body.insertBefore(shelf,body.firstChild);else body.appendChild(shelf);wireTeachingFavorites();document.querySelectorAll('[data-reread]').forEach(el=>el.onclick=()=>openStudyLesson(el.dataset.reread,true,teachingReturnTo(showKnowledgeChest)));};
openStudyBasket=function(){const ctx=teachingContext();if(!ctx)return teachingBasket();const {flow,p,s}=ctx,sec=studySection(),ready=flow.ready(p,s,sec.id);modal(`<span class="eyebrow">${learningCopy('基础确认与应用工坊','Foundations and application workshop')}</span><h2 id="dialogTitle">${esc(wt(sec.activity.title))}</h2><p>${esc(wt(sec.activity.brief))}</p><p>${learningCopy('可自由阅读全章。按顺序确认基础，再完成应用；不要求收齐或配对名称。','Browse the whole chapter freely. Confirm foundations in order, then complete applications; collecting or matching names is not required.')}</p><div class="knowledge-shelf">${sec.lessons.map(l=>`<button data-foundation-lesson="${l.id}">${p.foundations.includes(flow.foundation(sec.id,l.id)?.id)?'✓ ':''}${esc(knowledgeText(l,'title'))}</button>`).join('')}</div><p>${sec.lessons.filter(l=>p.foundations.includes(flow.foundation(sec.id,l.id)?.id)).length}/${sec.lessons.length} · ${learningCopy('基础已确认','foundations confirmed')}</p><div class="actions"><button id="basketBack">${learningCopy('返回场景','Back to scene')}</button><button id="sealBasket" class="primary" ${ready?'':'disabled'}>${learningCopy('启动应用工坊','Start application workshop')}</button></div>`,true);$('basketBack').onclick=close;$('sealBasket').onclick=openTaskWorkshop;document.querySelectorAll('[data-foundation-lesson]').forEach(el=>el.onclick=()=>openStudyLesson(el.dataset.foundationLesson,false,teachingReturnTo(openStudyBasket)));};
const teachingWorkshop=openTaskWorkshop;
openTaskWorkshop=function(){const ctx=teachingContext();if(!ctx)return teachingWorkshop();if(!ctx.flow.ready(ctx.p,ctx.s,studySection().id)){openStudyBasket();return;}workshopSelected=null;workshopEvidence=false;renderTaskWorkshop();};
const teachingSubmit=WorkshopEngine.submit;
WorkshopEngine.submit=function(s,sec,answer){const ctx=teachingContext();if(ctx&&s===ctx.s){const round=sec.activity.rounds[WorkshopEngine.progress(s,sec).round],step=ctx.flow.application(sec.id,round?.id);if(!step||!ctx.flow.gate(ctx.p,s,step.id))return false;}return teachingSubmit(s,sec,answer);};
const teachingSeal=CS.seal;
CS.seal=function(s,course){const entry=teachingEntry(course);if(entry){const p=state.teachingFlows?.[state.selected+':'+entry.binding],flow=TeachingFlow.create(entry);if(!p||!flow.complete(p,s,course.chapters[s.chapter].sections[s.section].id))return false;}return teachingSeal(s,course);};
const teachingDevice=sceneDeviceState;
sceneDeviceState=function(sec){const ctx=teachingContext();if(!ctx)return teachingDevice(sec);return ctx.flow.complete(ctx.p,ctx.s,sec.id)?'complete':ctx.flow.ready(ctx.p,ctx.s,sec.id)?'ready':'preview';};
const teachingControls={sort:['证据分类台','Evidence sorting desk'],order:['流程轨道','Process track'],choose:['情境决策桌','Scenario decision desk'],edit:['接线修复台','Repair bench'],number:['计算台','Calculation desk'],matrix:['权限柜','Permissions cabinet'],allocate:['资源盘','Resource planner'],rate:['证据仪表','Evidence gauge']};
const teachingPreview=previewSceneDevice;
previewSceneDevice=function(id){const ctx=teachingContext();if(!ctx)return teachingPreview(id);const sec=studyChapter().sections.find(x=>x.id===id);if(!sec)return;
 modal(`<span class="eyebrow">${learningCopy('自由探索 · 预览不计完成','Free exploration · previews do not count as completion')}</span><h2 id="dialogTitle">${esc(wt(sec.activity.title))}</h2><p>${esc(wt(sec.activity.brief))}</p><div class="knowledge-shelf">${sec.lessons.map(l=>`<button data-preview-lesson="${l.id}">${esc(knowledgeText(l,'title'))}</button>`).join('')}</div>${sec.activity.rounds.map((r,i)=>`<details><summary>${i+1} · ${learningCopy(...teachingControls[r.type])}</summary><p>${esc(wt(r.prompt))}</p></details>`).join('')}<p>${learningCopy('知识可随时查看；基础确认与应用提交遵守先修顺序。','Knowledge is always available; foundation confirmation and application submission respect prerequisites.')}</p><div class="actions"><button id="sceneDeviceBack">${learningCopy('返回场景','Back to scene')}</button><button id="sceneDeviceStart" ${sec.id===studySection().id?'':'disabled'}>${learningCopy('进入本节学习工坊','Enter section learning workshop')}</button></div>`,true);$('sceneDeviceBack').onclick=close;$('sceneDeviceStart').onclick=()=>{if(sec.id===studySection().id)openStudyBasket();};document.querySelectorAll('[data-preview-lesson]').forEach(el=>el.onclick=()=>openStudyLesson(el.dataset.previewLesson,true,teachingReturnTo(()=>previewSceneDevice(id))));};
const teachingRestore=L.restore;
L.restore=function(raw){const result=teachingRestore(raw);if(!result)return null;try{
 if(result.teachingFlows!==undefined&&(!result.teachingFlows||typeof result.teachingFlows!=='object'||Array.isArray(result.teachingFlows)))return null;
 const known=new Set();for(const b of result.banks){const entry=b.syllabus&&teachingEntry(b.syllabus,b.teachingSnapshot);if(!entry)continue;const s=result.chapterStudies?.[b.id];if(!s)return null;const key=b.id+':'+entry.binding;known.add(key);const p=result.teachingFlows?.[key];if(p){if(!TeachingFlow.create(entry).validate(p,s))return null;}else if(s.read.length||s.sealed.length||s.submitted.length||Object.keys(s.workshops||{}).length)return null;}
 if(Object.keys(result.teachingFlows||{}).some(key=>!known.has(key)))return null;return result;
 }catch{return null;}};
const teachingReplay=replayStudyChapter;
replayStudyChapter=function(){teachingReplay();const ctx=teachingContext();if(!ctx)return;const confirm=$('confirmStudyReplay'),base=confirm.onclick;confirm.onclick=()=>{const secs=ctx.entry.chapters[ctx.s.chapter].sections,ids=new Set(secs.flatMap(sec=>(sec.steps||ctx.flow.section(sec.id).steps).map(step=>step.id))),units=new Set(currentCourse().chapters[ctx.s.chapter].sections.flatMap(sec=>sec.lessons.map(l=>l.id)));ctx.p.found=ctx.p.found.filter(id=>!units.has(id));ctx.p.viewed=ctx.p.viewed.filter(id=>!units.has(id));ctx.p.favorites=ctx.p.favorites.filter(id=>!units.has(id));ctx.p.foundations=ctx.p.foundations.filter(id=>!ids.has(id));base();};};
